 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4 or grid[r][c] == 9]
    # The template consists of the non-background cells, excluding marker cells.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] not in (4, 9)]
    if not cells or not markers:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c, v in cells), max(r for r, c, v in cells)
    c0, c1 = min(c for r, c, v in cells), max(c for r, c, v in cells)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    shape = [(r - ar, c - ac, v) for r, c, v in cells]
    out = [[bg for _ in range(w)] for _ in range(h)]
    for mr, mc in markers:
        for dr, dc, v in shape:
            rr, cc = mr + dr, mc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out
